import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import styles from './Login.module.css';

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ username: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(form.username, form.password);
      navigate('/InstoreGO');
    } catch (err) {
      setError(err.response?.data?.message || 'Invalid username or password');
    } finally {
      setLoading(false);
    }
  };

  return (
      <div className={styles.page}>

        {/* Left panel — branding */}
        <div className={styles.brandPanel}>
          <div className={styles.brandInner}>
            <div className={styles.logo}>
              Instore<span className={styles.logoAccent}>Go</span>
              <span className={styles.logoDot} />
            </div>
            <h2 className={styles.brandHeadline}>
              Check items<br />before you<br /><em className={styles.brandEm}>step out.</em>
            </h2>
            <p className={styles.brandSub}>
              Real-time product availability at your nearest stores — no more wasted trips.
            </p>
            <div className={styles.featureList}>
              <div className={styles.featureItem}>
                <span className={styles.featureIcon}>🏪</span>
                <span>Browse nearby stores instantly</span>
              </div>
              <div className={styles.featureItem}>
                <span className={styles.featureIcon}>✅</span>
                <span>Live in-stock / out-of-stock status</span>
              </div>
              <div className={styles.featureItem}>
                <span className={styles.featureIcon}>🗂️</span>
                <span>Shop by category across stores</span>
              </div>
            </div>
          </div>

          {/* Decorative blobs */}
          <div className={styles.blob1} />
          <div className={styles.blob2} />
        </div>

        {/* Right panel — form */}
        <div className={styles.formPanel}>
          <div className={styles.formCard}>

            {/* Mobile logo (hidden on desktop) */}
            <div className={styles.mobileLogo}>
              Instore<span className={styles.logoAccent}>Go</span>
              <span className={styles.logoDot} />
            </div>

            <h1 className={styles.formTitle}>Welcome back</h1>
            <p className={styles.formSub}>Sign in to check availability at your stores</p>

            {error && (
                <div className={styles.errorBox}>
                  <span>⚠️</span> {error}
                </div>
            )}

            <form onSubmit={handleSubmit} className={styles.form}>
              <div className={styles.fieldGroup}>
                <label className={styles.label}>Username</label>
                <div className={styles.inputWrap}>
                  <span className={styles.inputIcon}>👤</span>
                  <input
                      className={styles.input}
                      name="username"
                      type="text"
                      value={form.username}
                      onChange={handleChange}
                      placeholder="Enter your username"
                      required
                      autoComplete="username"
                  />
                </div>
              </div>

              <div className={styles.fieldGroup}>
                <label className={styles.label}>Password</label>
                <div className={styles.inputWrap}>
                  <span className={styles.inputIcon}>🔒</span>
                  <input
                      className={styles.input}
                      name="password"
                      type={showPassword ? 'text' : 'password'}
                      value={form.password}
                      onChange={handleChange}
                      placeholder="Enter your password"
                      required
                      autoComplete="current-password"
                  />
                  <button
                      type="button"
                      className={styles.eyeBtn}
                      onClick={() => setShowPassword(v => !v)}
                      aria-label={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? '🙈' : '👁️'}
                  </button>
                </div>
              </div>

              <button
                  className={styles.submitBtn}
                  type="submit"
                  disabled={loading}
              >
                {loading ? (
                    <span className={styles.spinner} />
                ) : (
                    'Sign in →'
                )}
              </button>
            </form>

            <p className={styles.registerLink}>
              Don't have an account?{' '}
              <Link to="/register" className={styles.link}>Create one</Link>
            </p>
          </div>
        </div>
      </div>
  );
}
